/* Dedicated prepaid simulation ledger. Never used by gift, transfer or user checkout. */
(function(){
'use strict';
let tab='sent',busy=false;
const account=()=>String(actId()),money=n=>(Number(n)/100).toFixed(2),name=c=>c&&(c.remark||c.name)||'对方';
function cents(value){const s=String(value==null?'':value).trim();if(!/^\d{1,7}(?:\.\d{1,2})?$/.test(s))return null;const n=Math.round(Number(s)*100);return Number.isSafeInteger(n)&&n>0&&n<=100000000?n:null;}
function ledger(){if(!S.roleFamily)S.roleFamily={version:1,cards:[],orders:[]};if(S.roleFamily.version!==1||!Array.isArray(S.roleFamily.cards)||!Array.isArray(S.roleFamily.orders))throw Error('亲属卡记录异常，请恢复完整存档');return S.roleFamily;}
function cards(cid){return ledger().cards.filter(k=>k.account===account()&&(!cid||k.cid===cid));}
function roleOK(cid){const c=getC(cid);return c&&!c.deleted&&!c.blocked&&(isMain()||addedHere(c)||msgs(cid).length)?c:null;}
function card(id,cid){const k=cards(cid).find(k=>k.id===id);if(k&&(!['balance','funded','spent','refunded'].every(f=>Number.isSafeInteger(k[f])&&k[f]>=0)||k.balance!==k.funded-k.spent-k.refunded||!Array.isArray(k.events)))throw Error('卡片账目异常，已停止扣款');return k;}
function status(k){return({pending:'待对方收下',active:'使用中',frozen:'已暂停',declined:'对方已婉拒',revoked:'已撤回'})[k.status]||'不可用';}
function wallet(accountId){if(accountId===account())return S.me;return(S.me.accounts||[]).find(a=>a.id===accountId);}
function walletMove(accountId,delta,note,id){const w=wallet(accountId),bal=w&&Number(w.balance);if(!w||!Number.isFinite(bal)||bal<0||Math.round(bal*100)+delta<0)throw Error('你的模拟钱包余额不足');w.balance=(Math.round(bal*100)+delta)/100;w.bills=w.bills||[];w.bills.push({id,amount:Math.abs(delta)/100,type:delta>0?'in':'out',note,time:Date.now()});if(accountId===account()&&typeof syncActiveAccount==='function')syncActiveAccount();}
function event(k,kind,amount,note){k.events.push({id:uid(),kind,cents:amount,note,time:Date.now(),balance:k.balance});}
// One lock covers send/recharge/refund/purchase. Await the actual core persistence;
// a failed write restores balances, records and chat messages together.
async function transact(cid,fn){if(busy)return{ok:false,error:'上一笔操作正在保存，请稍后再试'};const ref=S,acct=account(),c=getC(cid),list=msgs(cid),before={ledger:JSON.stringify(S.roleFamily||null),balance:S.me.balance,bills:JSON.stringify(S.me.bills||[]),accounts:JSON.stringify(S.me.accounts||[]),messages:JSON.stringify(list),wallet:c&&c.wallet};busy=true;
 try{const result=fn();if(!await saveNowAsync())throw Error('保存未完成，本次余额没有扣除');if(S!==ref)throw Error('存档已切换，请在原存档查看结果');return{ok:true,result,account:acct};}
 catch(e){if(S===ref){S.roleFamily=JSON.parse(before.ledger);if(account()===acct){S.me.balance=before.balance;S.me.bills=JSON.parse(before.bills);}const owner=wallet(acct);if(owner){owner.balance=before.balance;owner.bills=JSON.parse(before.bills);}const row=(S.me.accounts||[]).find(a=>a.id===acct),oldRow=JSON.parse(before.accounts).find(a=>a.id===acct);if(row){row.balance=oldRow?oldRow.balance:before.balance;row.bills=oldRow?oldRow.bills:JSON.parse(before.bills);}list.splice(0,list.length,...JSON.parse(before.messages));if(c)c.wallet=before.wallet;try{await saveNowAsync();}catch(_){} }return{ok:false,error:e.message||'操作未完成'};}
 finally{busy=false;}
}
function offerNote(k){return '[亲属卡赠送事实：'+S.me.name+'从自己的模拟钱包预存了 ¥'+money(k.balance)+'，送给你一张只属于你的亲属卡，卡号标识 '+k.id+'。你要结合自己的人设、关系和当下意愿自主决定收下或拒绝，不能默认收下。收下时单独输出 [收下亲属卡|'+k.id+']；拒绝时 [拒绝亲属卡|'+k.id+']。可以自然说明心意。只有执行后才说收下。拒绝会把全额退回赠卡人。收下后只能给你自己买东西，不得给赠卡人或任何其他人购物、转账、提现。]';}
function familyRoleNotify(id){const k=card(id);if(!k||k.status!=='pending'||!roleOK(k.cid))return false;return scheduleReply(k.cid,offerNote(k));}
function familyRoleSendOpen(cid){const cs=(S.contacts||[]).filter(c=>roleOK(c.id));openModal(`<div class="rf-dialog"><small>一份只属于他的心意</small><h3>赠送亲属卡</h3><p>存入固定余额，供对方给自己买喜欢的东西。</p><label>赠给<select id="rfRecipient">${cs.map(c=>`<option value="${esc(c.id)}" ${cid===c.id?'selected':''}>${esc(name(c))}</option>`).join('')}</select></label><label>存入金额<input id="rfAmount" type="number" min="0.01" step="0.01" inputmode="decimal" placeholder="0.00"></label><label>卡片寄语<input id="rfNote" maxlength="80" placeholder="给自己买点喜欢的吧"></label><p class="rf-note">从你的模拟钱包扣入，拒收或撤回时余款原路退回。当前钱包 ¥${Number(S.me.balance||0).toFixed(2)}</p><div class="btns"><button class="btn" onclick="closeModal()">再想想</button><button class="btn p" onclick="familyRoleSend()">存入并赠送</button></div><p id="rfError" role="status"></p></div>`);}
async function familyRoleSend(){const cid=document.getElementById('rfRecipient')?.value,n=cents(document.getElementById('rfAmount')?.value),note=String(document.getElementById('rfNote')?.value||'给自己买点喜欢的吧').trim().slice(0,80);if(!roleOK(cid)||n===null){toast('选择角色，并填写有效金额（最多两位小数）');return false;}const result=await transact(cid,()=>{if(cards(cid).some(k=>['pending','active','frozen'].includes(k.status)))throw Error('这位角色已有你的亲属卡，可直接充值');const id='rfc_'+uid(),k={id,account:account(),cid,fromName:S.me.name,toName:name(getC(cid)),status:'pending',balance:n,funded:n,spent:0,refunded:0,note,createdAt:Date.now(),events:[]};walletMove(k.account,-n,'赠送给'+k.toName+'的亲属卡',id);event(k,'fund',n,'首次存入');ledger().cards.unshift(k);msgs(cid).push({id:uid(),role:'user',type:'rolefamilycard',cardId:id,account:k.account,time:Date.now()});return id;});if(!result.ok){toast(result.error);const e=document.getElementById('rfError');if(e)e.textContent=result.error;return false;}if(result.account!==account())return result.result;closeModal();tab='sent';go('wxfamily');familyRoleNotify(result.result);toast('专属卡片已发出，等待对方决定');return result.result;}
async function familyRoleDecide(id,cid,accept){const k=card(id,cid);if(!k||!roleOK(cid)||k.status!=='pending')return false;const result=await transact(cid,()=>{const k=card(id,cid);if(!k||k.status!=='pending')throw Error('这张卡已处理');if(accept){k.status='active';k.acceptedAt=Date.now();event(k,'accept',0,'对方收下');}else{const refund=k.balance;walletMove(k.account,refund,'亲属卡拒收退回',uid());k.balance=0;k.refunded+=refund;k.status='declined';event(k,'decline',refund,'拒收退回');}return k.status;});if(result.ok&&result.account===account()){if(cur().p==='chat'&&cur().id===cid)refreshChatMessages(cid);else if(cur().p==='wxfamily')render();}else if(!result.ok)toast(result.error);return result.ok;}
function familyRoleManage(id){const k=card(id);if(!k)return;const live=['pending','active','frozen'].includes(k.status);openModal(`<div class="rf-dialog"><small>赠给 ${esc(k.toName)} · ${esc(status(k))}</small><h3>专属亲属卡</h3><div class="rf-detail-balance">¥${money(k.balance)}</div><p>累计存入 ¥${money(k.funded)} · 已消费 ¥${money(k.spent)}${k.refunded?' · 已退回 ¥'+money(k.refunded):''}</p>${live?`<label>充值金额<input id="rfTopup" type="number" min="0.01" step="0.01" inputmode="decimal" placeholder="0.00"></label><button class="btn p rf-wide" onclick="familyRoleTopup('${k.id}')">从我的钱包充值</button><div class="rf-actions">${k.status==='pending'?`<button onclick="familyRoleNotify('${k.id}');closeModal()">请对方查看卡片</button>`:`<button onclick="familyRolePause('${k.id}')">${k.status==='frozen'?'恢复使用':'暂停使用'}</button>`}<button onclick="familyRoleRevoke('${k.id}')">撤回并退还余款</button></div>`:''}<h4>卡片流水</h4><div class="rf-ledger">${k.events.slice().reverse().map(e=>`<div><span>${esc(e.note)}<small>${new Date(e.time).toLocaleString('zh-CN')}</small></span><b>${e.cents?'¥'+money(e.cents):'—'}<small>余 ¥${money(e.balance)}</small></b></div>`).join('')}</div><button class="btn rf-wide" onclick="closeModal()">收好</button></div>`);}
async function familyRoleTopup(id){const k=card(id),n=cents(document.getElementById('rfTopup')?.value);if(!k||n===null){toast('请输入有效充值金额');return false;}const r=await transact(k.cid,()=>{const k=card(id);if(!k||!['pending','active','frozen'].includes(k.status))throw Error('这张卡已关闭');if(k.balance+n>100000000)throw Error('卡片余额最多 ¥1,000,000');walletMove(k.account,-n,'亲属卡充值 · '+k.toName,uid());k.balance+=n;k.funded+=n;event(k,'fund',n,'充值');});if(!r.ok){toast(r.error);return false;}if(r.account!==account())return true;familyRoleManage(id);render();toast('充值成功');return true;}
async function familyRolePause(id){const k=card(id);if(!k)return false;const r=await transact(k.cid,()=>{const k=card(id);if(!['active','frozen'].includes(k.status))throw Error('卡片尚未生效');k.status=k.status==='active'?'frozen':'active';event(k,'state',0,k.status==='frozen'?'暂停使用':'恢复使用');});if(!r.ok){toast(r.error);return false;}if(r.account!==account())return true;familyRoleManage(id);render();return true;}
async function familyRoleRevoke(id){const k=card(id);if(!k)return false;const r=await transact(k.cid,()=>{const k=card(id);if(!['pending','active','frozen'].includes(k.status))throw Error('已关闭，不会重复退回');const n=k.balance;walletMove(k.account,n,'亲属卡撤回余款 · '+k.toName,uid());k.balance=0;k.refunded+=n;k.status='revoked';event(k,'revoke',n,'撤回并退还余款');});if(!r.ok){toast(r.error);return false;}if(r.account!==account())return true;closeModal();render();toast('余款已退回你的模拟钱包');return true;}
// Orders use a durable business key. Buying for another person never enters this path.
async function familyRoleBuy(cid,orderId,item,amount,source,cardId,beneficiary){const n=cents(amount),c=roleOK(cid);if(!c||n===null||!item||String(item).length>80||!/^[A-Za-z0-9_-]{1,64}$/.test(orderId)||beneficiary!==cid||!['亲属卡','自己的银行'].includes(source))return{ok:false,error:'只支持金额有效、明确买给自己的订单'};const key=account()+':'+cid+':'+orderId,prior=ledger().orders.find(o=>o.key===key);if(prior)return prior.item===String(item)&&prior.cents===n&&prior.source===source&&prior.cardId===(source==='亲属卡'?cardId:null)?{ok:true,duplicate:true,result:prior}:{ok:false,error:'订单标识已使用，不能更改同一订单的付款内容'};const result=await transact(cid,()=>{if(ledger().orders.some(o=>o.key===key))throw Error('订单已处理');let k=null;if(source==='亲属卡'){k=card(cardId,cid);if(!k||k.status!=='active')throw Error('专属亲属卡未收下、已暂停或已关闭');if(k.balance<n)throw Error('亲属卡余额不足，不会改扣自己的银行');k.balance-=n;k.spent+=n;event(k,'spend',n,'给自己买 · '+item);}else{const d=S.spy&&S.spy[cid]||{},bal=spyBalance(c,d);if(!Number.isFinite(bal)||Math.round(bal*100)<n)throw Error('自己的银行余额不足，不会改扣亲属卡');c.wallet=(Math.round(bal*100)-n)/100;}
 const o={id:uid(),key,account:account(),cid,beneficiary:cid,item:String(item),cents:n,source,cardId:k&&k.id||null,time:Date.now()};ledger().orders.unshift(o);msgs(cid).push({id:uid(),role:'assistant',type:'rolefamilypurchase',orderId:o.id,account:o.account,time:o.time});return o;});if(result.ok&&result.account===account()){const m=msgs(cid).find(m=>m.orderId===result.result.id);if(m&&typeof notifyIncoming==='function')notifyIncoming(c,m);save(0);if(cur().p==='chat'&&cur().id===cid)refreshChatMessages(cid);}return result;}
async function familyRoleConsume(content,c){const pattern=/[\[【]\s*(收下亲属卡|拒绝亲属卡|自购)\s*[|｜]\s*([^\]】]*)[\]】]/g,text=String(content||''),hits=[...text.matchAll(pattern)],stateRef=S,acct=account();let failed=false;for(const h of hits){if(S!==stateRef||account()!==acct){failed=true;break;}const p=h[2].split(/[|｜]/).map(x=>x.trim());if(h[1]==='自购'){if(p.length!==5){toast('自购指令不完整，本次没有扣款');failed=true;continue;}const r=await familyRoleBuy(c.id,p[0],p[1],p[2],p[3],p[4],c.id);if(!r.ok){toast(r.error);failed=true;}}else if(p.length===1){const k=card(p[0],c.id),same=k&&(h[1]==='收下亲属卡'?k.status==='active':k.status==='declined');if(!same&&!await familyRoleDecide(p[0],c.id,h[1]==='收下亲属卡')){toast('这张亲属卡未完成处理，请查看卡片状态');failed=true;}}else failed=true;}return failed?'':text.replace(pattern,'').trim();}
function familyRolePrompt(c){const ks=cards(c.id).filter(k=>['pending','active','frozen'].includes(k.status));if(!ks.length)return '';return '\n# 对方赠给你的亲属卡（你的自购专用，独立于你给对方的月额度卡）\n'+ks.map(k=>'卡号 '+k.id+'：'+status(k)+'，余额 ¥'+money(k.balance)+'，累计消费 ¥'+money(k.spent)+'。').join('\n')+'\n待收下的卡由你依人设决定，使用 [收下亲属卡|卡号] 或 [拒绝亲属卡|卡号]。已收下且未暂停才可用。你可以结合自己的喜好自主买给自己；真实执行格式 [自购|唯一订单标识(字母数字下划线)|商品名|金额|亲属卡|卡号]，或 [自购|唯一订单标识|商品名|金额|自己的银行|无]。这些是小手机里的模拟购买。不能用亲属卡给对方或别人购物、送礼、转账、提现；此类支出只能走你自己的银行，绝不挪用亲属卡。金额不能超过对应余额，不得自动切换资金来源。手机购物列表里的旧展示订单不代表已扣此卡，余额与流水以执行结果为准。';}
function familyRoleHistory(m){if(m.account!==account())return '';if(m.type==='rolefamilycard'){const k=card(m.cardId);return k?'[我赠给你的专属自购亲属卡：卡号 '+k.id+'，'+status(k)+'，当前余额 ¥'+money(k.balance)+'。]':'';}const o=ledger().orders.find(o=>o.id===m.orderId&&o.account===account());return o?'[实际完成的模拟自购：'+o.item+'，¥'+money(o.cents)+'，支付来源 '+o.source+'，购买给你自己。]':'';}
function familyRoleBubble(m,c){if(m.account!==account())return '';if(m.type==='rolefamilycard'){const k=card(m.cardId,c.id);if(!k)return '<div class="rf-chat-card">这张卡的记录已不可用</div>';return `<button class="rf-chat-card" onclick="event.stopPropagation();familyRoleManage('${k.id}')"><div class="rf-mini-head"><span>亲属卡 · 赠给 ${esc(k.toName)}</span><i>✦</i></div><strong>¥${money(k.balance)}</strong><p>${esc(k.note)}</p><footer>${esc(status(k))}<span>专属自购卡 ›</span></footer></button>`;}const o=ledger().orders.find(o=>o.id===m.orderId&&o.account===account()&&o.cid===c.id);return o?`<div class="rf-purchase-card"><span>${esc(o.source)} · 已支付</span><b>${esc(o.item)}</b><strong>¥${money(o.cents)}</strong><small>买给${esc(name(c))}自己 · 已记入购物与银行</small></div>`:'';}
function familyRoleBank(cid){const ks=cards(cid),os=ledger().orders.filter(o=>o.account===account()&&o.cid===cid);if(!ks.length&&!os.length)return '';return `<section class="rf-bank"><h3>对方赠给我的亲属卡</h3>${ks.map(k=>`<div class="rf-bank-card"><span>${esc(k.fromName)}赠予 · ${esc(status(k))}</span><b>¥${money(k.balance)}</b><small>亲属卡剩余余额 · 仅给自己购物</small></div>`).join('')}<h4>已执行的购物支出</h4>${os.map(o=>`<div class="rf-bank-row"><span>${esc(o.item)}<small>${esc(o.source)} · ${new Date(o.time).toLocaleDateString('zh-CN')}</small></span><b>−¥${money(o.cents)}</b></div>`).join('')||'<p>还没有亲属卡消费</p>'}</section>`;}
function familyRoleShop(cid){return ledger().orders.filter(o=>o.account===account()&&o.cid===cid).map(o=>`<div class="rf-order"><div><b>${esc(o.item)}</b><span>¥${money(o.cents)}</span></div><p><em>${esc(o.source)}</em> 买给自己 · 已下单</p><small>${new Date(o.time).toLocaleString('zh-CN')}</small></div>`).join('');}
function familyRoleTab(value){tab=value==='received'?'received':'sent';render();}
function familyRolePage(){const ks=cards(),received=(S.contacts||[]).filter(c=>!c.deleted&&c.family&&c.family.bound);return `<div class="wx-directory-head"><div class="wx-real-nav titled"><button onclick="back()">‹</button><b>亲属卡</b><span></span></div></div><main class="scroll rf-page"><div class="rf-intro"><span>FAMILY & CARE</span><h1>把心意，留在身边</h1><p>一张专属卡，一份被记得的关心。</p></div><div class="rf-tabs"><button class="${tab==='sent'?'on':''}" onclick="familyRoleTab('sent')">我赠出的</button><button class="${tab==='received'?'on':''}" onclick="familyRoleTab('received')">我收到的</button></div>${tab==='sent'?`<button class="rf-new" onclick="familyRoleSendOpen()"><i>＋</i><span><b>赠送一张亲属卡</b><small>存入余额，只供对方给自己购物</small></span><em>›</em></button>${ks.length?ks.map(k=>`<button class="rf-premium ${['revoked','declined'].includes(k.status)?'closed':''}" onclick="familyRoleManage('${k.id}')"><i class="rf-orbit"></i><div class="rf-top"><span>FAMILY PRIVILEGE</span><small>${esc(status(k))}</small></div><div class="rf-owner">${av(getC(k.cid)?.avatar,'sm')}<span>赠给<b>${esc(k.toName)}</b></span><i class="rf-chip"></i></div><div class="rf-card-money"><small>专属卡剩余余额</small><b>¥${money(k.balance)}</b></div><p>${esc(k.note)}</p><footer><span>累计消费 ¥${money(k.spent)}</span><span>管理卡片 ↗</span></footer></button>`).join(''):'<div class="rf-empty">选一位想关心的人，送出第一张专属卡。</div>'}<p class="rf-page-note">你存入的钱与对方的银行余额分开保存。<br>对方可按自己的意愿收下或拒绝；未用余款可退回。</p>`:received.length?received.map(c=>{const f=c.family,used=f.month===curMonth()?(Number(f.used)||0):0,q=Number(f.quota)||0;return `<button class="rf-premium rf-received" onclick="cFamily('${c.id}')"><i class="rf-orbit"></i><div class="rf-top"><span>GIVEN WITH CARE</span><small>对方给我的月额度卡</small></div><div class="rf-owner">${av(c.avatar,'sm')}<span>来自<b>${esc(name(c))}</b></span><i class="rf-chip"></i></div><div class="rf-card-money"><small>本月剩余额度</small><b>¥${Math.max(0,q-used).toFixed(2)}</b></div><footer><span>每月额度 ¥${q.toFixed(2)}</span><span>本月已用 ¥${used.toFixed(2)}</span></footer></button>`;}).join(''):'<div class="rf-empty">还没有收到亲属卡。<br>在角色聊天的 ＋ → 亲属卡中可以向对方申请。</div>'}</main>`;}
Object.assign(window,{renderWxFamily:familyRolePage,familyRoleTab,familyRoleSendOpen,familyRoleSend,familyRoleNotify,familyRoleManage,familyRoleTopup,familyRolePause,familyRoleRevoke,familyRoleConsume,familyRolePrompt,familyRoleHistory,familyRoleBubble,familyRoleBank,familyRoleShop,__roleFamily:{busy:()=>busy,cents,ledger,cards,decide:familyRoleDecide,buy:familyRoleBuy,status,transact}});
})();
